ClockGatingResult ClockGatingService::close(){auto& p=*impl_;ClockGatingResult out;Guard guard(p.api.transport,p.gpu);if(!guard.held){out.message="GPU lock unavailable; owned profiler cleanup retained";return out;}out.ok=true;for(size_t i=0;i<3;++i)if(p.owners[i].handle||p.owners[i].probe){const auto release=p.release_one(Family(i));out.may_have_changed=out.may_have_changed||release.may_have_changed;out.ok=out.ok&&release.ok;if(!release.ok){if(!out.message.empty())out.message+="; ";out.message+=release.message;}}p.flags();if(out.message.empty())out.message="Owned profiler objects released/freed; PCIe target not replayed";p.data.message=out.message;return out;}
